#include <stddef.h>
#include <stdint.h>
#include <math.h>
static void put(uint8_t*o,size_t p,double x){union{double f;uint64_t u;}b={.f=x};for(size_t k=0;k<8;k++)o[p+k]=(uint8_t)(b.u>>(8*k));}
int64_t gauss_jordan(const int64_t*v,size_t n,uint8_t*out,size_t cap){if(!v||n<2||n>22)return -1;int64_t r=v[0],c=v[1];if(r<1||r>4||c<1||c>4||n!=2+(size_t)(r*c+r))return -1;double a[4][4]={{0}},b[4]={0};for(int64_t i=0;i<r;i++)for(int64_t j=0;j<c;j++){int64_t z=v[2+i*c+j];if(z < -5000||z>5000)return -1;a[i][j]=(double)z/1000.0;}for(int64_t i=0;i<r;i++){int64_t z=v[2+r*c+i];if(z < -5000||z>5000)return -1;b[i]=(double)z/1000.0;}size_t count=(size_t)(r*c+r),bytes=count*8;if(!out||cap<bytes)return -2;for(int64_t col=0;col<c;col++){int64_t pivot=-1;for(int64_t row=col;row<r;row++)if(fabs(a[row][col])>1e-8){pivot=row;break;}if(pivot<0)continue;if(pivot!=col){for(int64_t j=0;j<c;j++){double t=a[col][j];a[col][j]=a[pivot][j];a[pivot][j]=t;}double t=b[col];b[col]=b[pivot];b[pivot]=t;}double pv=a[col][col];for(int64_t j=0;j<c;j++)a[col][j]/=pv;b[col]/=pv;for(int64_t row=0;row<r;row++){if(row==col)continue;double f=a[row][col];for(int64_t j=0;j<c;j++)a[row][j]-=f*a[col][j];b[row]-=f*b[col];}}size_t at=0;for(int64_t i=0;i<r;i++)for(int64_t j=0;j<c;j++)put(out,at++*8,a[i][j]);for(int64_t i=0;i<r;i++)put(out,at++*8,b[i]);return (int64_t)bytes;}
